    $config = Read-TaskForgeConfig -Path $configFile
    $dataFile = if ($options.Contains('data-file')) {
        Resolve-TaskForgePath -Path (Get-RequiredOption -Options $options -Name 'data-file') -ConfigFile $configFile
    }
    elseif ($null -ne $config.dataFile) {
        Resolve-TaskForgePath -Path ([string]$config.dataFile) -ConfigFile $configFile
    }
    else {
        $defaultDataFile
    }
    if ($options.Contains('json') -and $options.Contains('no-json')) {
        throw '--json and --no-json cannot be used together.'
    }
    $asJson = if ($options.Contains('no-json')) {
        $false
    }
    elseif ($options.Contains('json')) {
        ConvertTo-TaskForgeBoolean -Value $options['json'] -Name '--json'
    }
    else {
        [bool]$config.defaultJson
    }

    switch ($Command.ToLowerInvariant()) {
        'add' {
            Assert-KnownOptions -Options $options -Allowed @('title', 'description', 'data-file', 'config-file', 'json', 'no-json')
            $title = Get-RequiredOption -Options $options -Name 'title'
            $tasks = @(Read-TaskStore -Path $dataFile)
            $nextId = if ($tasks.Count -eq 0) { 1 } else { 1 + [int](($tasks | Measure-Object -Property id -Maximum).Maximum) }
            $task = [ordered]@{
                id = $nextId
                title = $title.Trim()
                description = if ($options.Contains('description')) { [string]$options['description'] } else { '' }
                status = 'pending'
                createdAt = [DateTimeOffset]::UtcNow.ToString('o')
            }
            Write-TaskStore -Path $dataFile -Tasks @($tasks + [pscustomobject]$task)
            if ($asJson) {
                Write-TaskForgeOutput -Value ([pscustomobject]$task) -AsJson $true
            }
            else {
                "Added task ${nextId}: $($task.title)"
            }
        }
        'list' {
            Assert-KnownOptions -Options $options -Allowed @('data-file', 'config-file', 'json', 'no-json')
            $tasks = @(Read-TaskStore -Path $dataFile | Sort-Object { [int]$_.id })
            if ($asJson) {
                Write-TaskForgeOutput -Value $tasks -AsJson $true
            }
            elseif ($tasks.Count -eq 0) {
                'No tasks.'
            }
            else {
                $tasks | ForEach-Object { "[{0}] #{1} {2}" -f $_.status, $_.id, $_.title }
            }
        }
        'complete' {
            Assert-KnownOptions -Options $options -Allowed @('id', 'data-file', 'config-file', 'json', 'no-json')
            $idText = Get-RequiredOption -Options $options -Name 'id'
            $id = 0
            if (-not [int]::TryParse($idText, [ref]$id) -or $id -le 0) {
                throw '--id must be a positive integer.'
            }
            $tasks = @(Read-TaskStore -Path $dataFile)
            $task = $tasks | Where-Object { [int]$_.id -eq $id } | Select-Object -First 1
            if ($null -eq $task) {
                throw "Task $id was not found."
            }
            $task.status = 'completed'
            Write-TaskStore -Path $dataFile -Tasks $tasks
            if ($asJson) {
                Write-TaskForgeOutput -Value $task -AsJson $true
            }
            else {
                "Completed task $id."
            }
        }
        'remove' {
            Assert-KnownOptions -Options $options -Allowed @('id', 'data-file', 'config-file', 'json', 'no-json')
            $idText = Get-RequiredOption -Options $options -Name 'id'
            $id = 0
            if (-not [int]::TryParse($idText, [ref]$id) -or $id -le 0) {
                throw '--id must be a positive integer.'
            }
            $tasks = @(Read-TaskStore -Path $dataFile)
            $remaining = @($tasks | Where-Object { [int]$_.id -ne $id })
            if ($remaining.Count -eq $tasks.Count) {
                throw "Task $id was not found."
            }
            Write-TaskStore -Path $dataFile -Tasks $remaining
            $summary = [pscustomobject]@{ removedId = $id }
            if ($asJson) {
                Write-TaskForgeOutput -Value $summary -AsJson $true
            }
            else {
                "Removed task $id."
            }
        }
        'config' {
            Assert-KnownOptions -Options $options -Allowed @('config-file', 'json', 'no-json')
            $supportedKeys = @('dataFile', 'defaultJson')
            if ($configAction -in @('set', 'get') -and $configKey -notin $supportedKeys) {
                throw "Unknown configuration key: $configKey"
            }

            switch ($configAction) {
                'set' {
                    $newConfig = [ordered]@{
                        dataFile = $config.dataFile
                        defaultJson = [bool]$config.defaultJson
                    }
                    if ($configKey -eq 'dataFile') {
                        if ([string]::IsNullOrWhiteSpace($configValue)) {
                            throw 'dataFile must be a non-empty path.'
                        }
                        $newConfig.dataFile = $configValue
                    }
                    else {
                        $newConfig.defaultJson = ConvertTo-TaskForgeBoolean -Value $configValue -Name 'defaultJson'
                    }
                    Write-TaskForgeConfig -Path $configFile -Config $newConfig
                    $result = [pscustomobject]@{ key = $configKey; value = $newConfig[$configKey] }
                    if ($asJson) {
                        Write-TaskForgeOutput -Value $result -AsJson $true
                    }
                    else {
                        "Set $configKey = $($newConfig[$configKey])"
                    }
                }
                'get' {
                    $value = if ($configKey -eq 'dataFile' -and $null -eq $config.dataFile) {
                        $defaultDataFile
                    }
                    else {
                        $config[$configKey]
                    }
                    if ($asJson) {
                        Write-TaskForgeOutput -Value ([pscustomobject]@{ key = $configKey; value = $value }) -AsJson $true
                    }
                    else {
                        [string]$value
                    }
                }
                'list' {
                    $settings = [ordered]@{
                        dataFile = if ($null -eq $config.dataFile) { $defaultDataFile } else { $config.dataFile }
                        defaultJson = [bool]$config.defaultJson
                    }
                    if ($asJson) {
                        Write-TaskForgeOutput -Value $settings -AsJson $true
                    }
                    else {
                        Get-Content -LiteralPath (Join-Path $repositoryRoot 'assets/config.txt')
                        "dataFile = $($settings.dataFile)"
                        "defaultJson = $($settings.defaultJson.ToString().ToLowerInvariant())"
                    }
                }
            }
        }
        'help' {
            Assert-KnownOptions -Options $options -Allowed @('config-file')
            @'
TaskForge
  add --title TEXT [--description TEXT] [--data-file PATH] [--json|--no-json]
  list [--data-file PATH] [--json|--no-json]
  complete --id ID [--data-file PATH] [--json|--no-json]
  remove --id ID [--data-file PATH] [--json|--no-json]
  config set dataFile PATH [--json|--no-json]
  config set defaultJson true|false [--json|--no-json]
  config get dataFile|defaultJson [--json|--no-json]
  config list [--json|--no-json]
  All commands accept --config-file PATH.
'@
        }
        default {
            throw "Unknown command: $Command"
        }
    }
}
catch {
    [Console]::Error.WriteLine("TaskForge: $($_.Exception.Message)")
    exit 1
}
